class AssignSeg:
    INF = {{NEG_INF}}
    def __init__(self, n={{n}}):
        self.n = n
        self.t = [self.INF]*(4*n)
        self.lz = [None]*(4*n)
    def push(self, p):
        if self.lz[p] is not None:
            for c in (2*p, 2*p+1):
                self.t[c] = self.lz[p]; self.lz[c] = self.lz[p]
            self.lz[p] = None
    def assign(self, ql, qr, v, p=1, l=0, r=None):
        if r is None: r = self.n-1
        if ql <= l and r <= qr:
            self.t[p] = v; self.lz[p] = v; return
        self.push(p); m = (l+r)//2
        if ql <= m: self.assign(ql,qr,v,2*p,l,m)
        if qr > m: self.assign(ql,qr,v,2*p+1,m+1,r)
        self.t[p] = max(self.t[2*p], self.t[2*p+1])
    def query(self, ql, qr, p=1, l=0, r=None):
        if r is None: r = self.n-1
        if ql <= l and r <= qr: return self.t[p]
        self.push(p); m = (l+r)//2; res = self.INF
        if ql <= m: res = max(res, self.query(ql,qr,2*p,l,m))
        if qr > m: res = max(res, self.query(ql,qr,2*p+1,m+1,r))
        return res
